let content = "";
const firstItem = $input.first();

// Try reading via n8n's official helper (most robust for binary objects)
if (firstItem.binary && firstItem.binary.data) {
    try {
        const buffer = await this.helpers.getBinaryDataBuffer(0, 'data');
        const utf8Text = buffer.toString('utf-8');
        const utf16Text = buffer.toString('utf16le');
        if (utf8Text.includes('const') || utf8Text.includes('menuData')) {
            content = utf8Text;
        } else if (utf16Text.includes('const') || utf16Text.includes('menuData')) {
            content = utf16Text;
        }
    } catch (e) {}
}

// Fallback to reading JSON properties if binary helper failed or didn't return text
if (!content && firstItem.json) {
    if (firstItem.json.fileContent) {
        content = firstItem.json.fileContent;
    } else if (firstItem.json.content) {
        let rawContent = firstItem.json.content;
        if (firstItem.json.encoding === 'base64' || (!rawContent.includes('const') && !rawContent.includes('menuData'))) {
            try {
                const cleanBase64 = rawContent.replace(/\s/g, '');
                const buf = Buffer.from(cleanBase64, 'base64');
                const utf8Text = buf.toString('utf-8');
                const utf16Text = buf.toString('utf16le');
                if (utf8Text.includes('const') || utf8Text.includes('menuData')) {
                    content = utf8Text;
                } else if (utf16Text.includes('const') || utf16Text.includes('menuData')) {
                    content = utf16Text;
                } else {
                    content = utf8Text;
                }
            } catch (err) {
                content = rawContent;
            }
        } else {
            content = rawContent;
        }
    }
}

if (!content) {
    throw new Error("Could not read menu.js content");
}

// Strip BOM if present
let prefixBOM = "";
if (content.charCodeAt(0) === 0xFEFF) {
    prefixBOM = "\uFEFF";
    content = content.slice(1);
}

const startIndex = content.indexOf('[');
const endIndex = content.lastIndexOf(']');
if (startIndex === -1 || endIndex === -1) {
    throw new Error("Could not find array in menu.js");
}

const jsonStr = content.substring(startIndex, endIndex + 1);
const menuData = JSON.parse(jsonStr);

// Find first item with placeholder
let itemToUpdate = null;
for (const category of menuData) {
    for (const item of category.items || []) {
        if (item.image === 'logo.png') {
            itemToUpdate = item;
            break;
        }
    }
    if (itemToUpdate) break;
}

if (!itemToUpdate) {
    throw new Error("All items already have images!");
}

const itemName = itemToUpdate.name;
const cleanName = itemName.toLowerCase().replace(/\s+/g, '_').replace(/[^a-z0-9_]/g, '');
const relativeImagePath = `assets/images/${cleanName}_ai.png`;

// Update in memory
itemToUpdate.image = relativeImagePath;

// Construct new menu.js content
const updatedJsonStr = JSON.stringify(menuData, null, 4);
const newMenuJsContent = prefixBOM + content.substring(0, startIndex) + updatedJsonStr + content.substring(endIndex + 1);

return {
    json: {
        itemName: itemName,
        cleanName: cleanName,
        imagePath: relativeImagePath,
        newMenuJsContent: newMenuJsContent
    }
};

